from pipeline import Pipeline

def test_pipeline():
    p = Pipeline()
    p.use(lambda r: {**r, 'a': 1})
    p.use(lambda r: {**r, 'b': 2})
    assert p.execute({}) == {'a': 1, 'b': 2}

